import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        // Split on '\n' only; IDs keep their spaces. Decoding and re-encoding UTF-8 is lossless.
        String[] lines = new String(System.in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8).split("\n", -1);
        StringTokenizer header = new StringTokenizer(lines[0]);
        int n = Integer.parseInt(header.nextToken()), k = Integer.parseInt(header.nextToken());
        int last = Math.min(n, lines.length - 1);
        HashSet<String> seen = new HashSet<>();
        ArrayList<String> out = new ArrayList<>();
        for (int i = last; i >= 1; i--) {
            if (!seen.add(lines[i])) continue;
            out.add(lines[i]);
            if (out.size() == k) break;
        }
        StringBuilder res = new StringBuilder();
        if (out.size() < k) res.append("-1\n");
        else {
            res.append(k);
            for (String v : out) res.append('\n').append(v);
            res.append('\n');
        }
        System.out.write(res.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));
        System.out.flush();
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"bytes"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	// Split on '\n' only; IDs keep their spaces.
	lines := bytes.Split(data, []byte("\n"))
	header := bytes.Fields(lines[0])
	n, _ := strconv.Atoi(string(header[0]))
	k, _ := strconv.Atoi(string(header[1]))
	last := min(n, len(lines)-1)
	seen := map[string]bool{}
	out := make([][]byte, 0, k)
	for i := last; i >= 1; i-- {
		if seen[string(lines[i])] {
			continue
		}
		seen[string(lines[i])] = true
		out = append(out, lines[i])
		if len(out) == k {
			break
		}
	}
	if len(out) < k {
		w.WriteString("-1\n")
		return
	}
	w.WriteString(strconv.Itoa(k))
	for _, v := range out {
		w.WriteByte('\n')
		w.Write(v)
	}
	w.WriteByte('\n')
}
